const show = v =>
  v === null || v === undefined || v === ''
    ? 'null'
    : v;

const response = $json;

const events =
  response?.pagedList?.items ??
  response?.pagedList?.Items ??
  response?.items ??
  response?.Items ??
  [];

return events.map(event => {

  const firstDate = event?.dates?.[0] ?? {};

  const rawTime = String(
    firstDate.timeBeautified ||
    event.timeBeautified ||
    ''
  );

  const timeParts = rawTime.split(/\s*-\s*/);

  // -----------------------------------------
  // EVENT URL
  // -----------------------------------------

  let eventUrl = event?.url || null;

  if (eventUrl) {

    eventUrl = String(eventUrl).trim();

    if (eventUrl.startsWith('/')) {
      eventUrl =
        'https://www.uitagendarotterdam.nl' +
        eventUrl;
    }

  } else {

    // Fallback: generate URL from event title
    const slug = String(event?.title || '')
      .toLowerCase()
      .trim()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');

    if (slug) {
      eventUrl =
        `https://www.uitagendarotterdam.nl/agenda/${slug}/`;
    }
  }

  return {
    json: {

      source: 'uitagenda',

      source_event_id:
        show(event.id),

      event_name:
        show(event.title),

      event_date:
        show(event.date),

      event_time:
        show(timeParts[0]),

      end_date:
        show(event.dateEnd),

      timezone:
        'Europe/Amsterdam',

      venue:
        show(event?.location?.title),

      venue_latitude:
        show(event?.geoLocation?.latitude),

      venue_longitude:
        show(event?.geoLocation?.longitude),

      city:
        show(
          event?.location?.city ||
          'Rotterdam'
        ),

      country:
        show(
          event?.location?.country === 'NL'
            ? 'Netherlands'
            : event?.location?.country ||
              'Netherlands'
        ),

      description:
        show(
          event.text ||
          event.textShort
        ),

      ticket_link:
        show(firstDate.ticketUrl),

      image_url:
        event.image
          ? `https://www.uitagendarotterdam.nl${event.image}`
          : 'null',

      event_url:
        eventUrl || 'null',

      scrape_status:
        'success'
    }
  };
});

const httpItems = $input.all();
const originalItems = $('Normalize Event Data').all();

function decodeHtml(str) {
  return String(str || '')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function cleanUrl(url) {
  if (!url) return null;

  url = decodeHtml(url).trim();

  if (!url) return null;

  if (url.startsWith('//')) {
    return 'https:' + url;
  }

  if (url.startsWith('/')) {
    return 'https://www.uitagendarotterdam.nl' + url;
  }

  return url;
}

function extractTicketLink(html) {
  if (!html) return null;

  const anchorRegex =
    /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;

  const anchors = [];

  for (const match of html.matchAll(anchorRegex)) {
    const href = cleanUrl(match[1]);
    const innerHtml = match[2] || '';

    const text = decodeHtml(
      innerHtml
        .replace(/<[^>]+>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
    ).toLowerCase();

    if (!href) continue;

    anchors.push({
      href,
      text
    });
  }

  // --------------------------------------------------
  // 1. Strong ticket-link text match
  // --------------------------------------------------

  const strongTicketTexts = [
    'buy tickets',
    'buy ticket',
    'tickets kopen',
    'tickets bestellen',
    'bestel tickets',
    'koop tickets',
    'koop ticket',
    'kaartjes kopen',
    'kaartjes bestellen'
  ];

  for (const anchor of anchors) {
    if (
      strongTicketTexts.some(keyword =>
        anchor.text.includes(keyword)
      )
    ) {
      return anchor.href;
    }
  }

  // --------------------------------------------------
  // 2. Generic ticket text match
  // --------------------------------------------------

  for (const anchor of anchors) {
    if (
      anchor.text === 'ticket' ||
      anchor.text === 'tickets' ||
      anchor.text.includes('ticket')
    ) {
      return anchor.href;
    }
  }

  // --------------------------------------------------
  // 3. Ticket-related URL match
  // --------------------------------------------------

  for (const anchor of anchors) {
    const urlLower = anchor.href.toLowerCase();

    if (
      /ticket|tickets|buyticket|buy-tickets|tickets-kopen|kaartjes/.test(
        urlLower
      )
    ) {
      return anchor.href;
    }
  }

  return null;
}


// --------------------------------------------------
// Process every event
// --------------------------------------------------

return originalItems.map((originalItem, index) => {
  const original = originalItem.json || {};
  const httpItem = httpItems[index];

  const html = String(
    httpItem?.json?.event_page_html || ''
  );

  const extractedTicketLink = extractTicketLink(html);

  // Keep existing API ticket link if page scraping
  // did not find anything
  const existingTicketLink =
    original.ticket_link &&
    original.ticket_link !== 'null' &&
    original.ticket_link !== ''
      ? original.ticket_link
      : null;

  const finalTicketLink =
    extractedTicketLink || existingTicketLink || 'null';

  return {
    json: {
      ...original,

      ticket_link: finalTicketLink,

      scrape_status: extractedTicketLink
        ? 'success'
        : existingTicketLink
          ? 'success_api_ticket_link'
          : 'success_no_ticket_link'
    }
  };
});

const show = v => (v === null || v === undefined || v === '' ? 'null' : v);
const events = $input.all();

let content = `KYNCT – Uitagenda Scraped Events
================================

IMPORT SUMMARY
--------------
Source: Uitagenda Rotterdam
Location: Rotterdam, Netherlands
Events imported: ${events.length}

`;

events.forEach((i, n) => {
  const e = i.json;

  content += `EVENT ${n + 1}
--------------------
Event Name: ${show(e.event_name)}
Date: ${show(e.event_date)}
Time: ${show(e.event_time)}
Timezone: ${show(e.timezone)}
End Date: ${show(e.end_date)}
Venue: ${show(e.venue)}
Venue Latitude: ${show(e.venue_latitude)}
Venue Longitude: ${show(e.venue_longitude)}
City: ${show(e.city)}
Country: ${show(e.country)}

Description:
${show(e.description)}

Ticket Link:
${show(e.ticket_link)}

Image URL:
${show(e.image_url)}

Event URL:
${show(e.event_url)}

Source: ${show(e.source)}
Source Event ID: ${show(e.source_event_id)}

----------------------------------------

`;
});

return [{
  json: {
    title: 'KYNCT – Uitagenda Scraped Events',
    document_content: content
  }
}];

const existingItems = $input.all();
const currentItems = $('Extract Ticket Link').all();


// =====================================================
// 1. EXISTING GOOGLE SHEET EVENTS
//    source_event_id is the ONLY matching key
// =====================================================

const existingMap = new Map();

for (const item of existingItems) {

  const existing = item.json || {};

  const sourceEventId = String(
    existing.source_event_id ?? ''
  ).trim();

  if (sourceEventId !== '') {
    existingMap.set(sourceEventId, existing);
  }
}


// =====================================================
// 2. FIELDS TO COMPARE
//    Only checked AFTER source_event_id matches
// =====================================================

const compareFields = [
  'event_name',
  'description',
  'event_date',
  'event_time',
  'end_date',
  'venue',
  'venue_latitude',
  'venue_longitude',
  'city',
  'country',
  'ticket_link',
  'image_url',
  'timezone',
  'source',
  'event_url'
];


// =====================================================
// 3. NORMALIZE VALUES
// =====================================================

function normalize(field, value) {

  // Treat null / empty values as the same
  if (
    value === null ||
    value === undefined ||
    value === '' ||
    String(value).trim().toLowerCase() === 'null'
  ) {
    return '';
  }

  let v = String(value).trim();


  // ---------------------------------------------
  // Normalize date format
  // ---------------------------------------------
  //
  // 2026-10-06T10:30:00
  // 2026-10-06 10:30:00
  //
  // Both become:
  // 2026-10-06 10:30:00
  //

  if (
    field === 'event_date' ||
    field === 'end_date'
  ) {
    v = v.replace('T', ' ');
    v = v.replace(/Z$/, '');
    v = v.trim();
  }


  // ---------------------------------------------
  // Normalize extra spaces
  // ---------------------------------------------

  v = v.replace(/\s+/g, ' ');


  // ---------------------------------------------
  // Normalize URLs
  // ---------------------------------------------

  if (
    field === 'ticket_link' ||
    field === 'image_url' ||
    field === 'event_url'
  ) {
    v = v.replace(/\/$/, '');
  }


  // ---------------------------------------------
  // Normalize coordinates
  // ---------------------------------------------

  if (
    field === 'venue_latitude' ||
    field === 'venue_longitude'
  ) {

    const numberValue = Number(v);

    if (!Number.isNaN(numberValue)) {
      return numberValue.toFixed(6);
    }
  }


  return v;
}


// =====================================================
// 4. COUNTERS
// =====================================================

let newCount = 0;
let updatedCount = 0;
let unchangedCount = 0;


// =====================================================
// 5. ONLY NEW + UPDATED EVENTS WILL BE STORED
// =====================================================

const results = [];


// =====================================================
// 6. COMPARE CURRENT EVENTS WITH GOOGLE SHEET
// =====================================================

for (const item of currentItems) {

  const current = item.json || {};


  // ---------------------------------------------
  // Current source_event_id
  // ---------------------------------------------

  const sourceEventId = String(
    current.source_event_id ?? ''
  ).trim();


  // ---------------------------------------------
  // Match ONLY by source_event_id
  // ---------------------------------------------

  const existing = existingMap.get(sourceEventId);


  // =================================================
  // CASE 1: NEW EVENT
  // source_event_id does not exist in Sheet
  // =================================================

  if (!existing) {

    newCount++;

    results.push({
      json: {
        ...current,

        change_type: 'new',

        differences: {}
      }
    });

    continue;
  }


  // =================================================
  // CASE 2: EXISTING EVENT
  // source_event_id matched
  // Compare all fields
  // =================================================

  const differences = {};


  for (const field of compareFields) {

    const currentValue = normalize(
      field,
      current[field]
    );

    const sheetValue = normalize(
      field,
      existing[field]
    );


    // ---------------------------------------------
    // Actual field change detected
    // ---------------------------------------------

    if (currentValue !== sheetValue) {

      differences[field] = {
        current: currentValue,
        sheet: sheetValue
      };
    }
  }


  // =================================================
  // CASE 2A: EVENT UPDATED
  // =================================================

  if (Object.keys(differences).length > 0) {

    updatedCount++;

    results.push({
      json: {
        ...current,

        change_type: 'updated',

        differences
      }
    });

  }


  // =================================================
  // CASE 2B: EVENT UNCHANGED
  // =================================================
  //
  // IMPORTANT:
  // Do NOT push this event into results.
  //
  // Nothing will be sent to the next node.
  //

  else {

    unchangedCount++;
  }
}


// =====================================================
// 7. RETURN ONLY NEW + UPDATED EVENTS
// =====================================================
//
// IMPORTANT:
// Unchanged events are NOT returned.
//

return results.map(item => ({
  json: {

    ...item.json,

    new_count: newCount,

    updated_count: updatedCount,

    unchanged_count: unchangedCount,

    // Google Doc should be created
    // if at least one event is new OR updated
    should_create_doc:
      newCount > 0 ||
      updatedCount > 0
  }
}));
